import subprocess
import os

def get_network_interfaces():
    """Zwraca listę kart sieciowych."""
    try:
        output = subprocess.check_output(["ip", "addr", "show"]).decode('utf-8')
        interfaces = [line.split()[1] for line in output.split('\n') if 'inet' in line]
        return interfaces
    except subprocess.CalledProcessError:
        print("Błąd przy odczycie kart sieciowych.")
        return []

def disable_network_interface(interface_name):
    """Wyłącz kartę sieciową."""
    try:
        subprocess.run(["sudo", "ifconfig", interface_name, "down"], check=True)
        print(f"Karta {interface_name} została wyłączona.")
    except subprocess.CalledProcessError as e:
        print(f"Błąd przy wyłączaniu karty {interface_name}: {e}")

def enable_network_interface(interface_name):
    """Włącz kartę sieciową."""
    try:
        subprocess.run(["sudo", "ifconfig", interface_name, "up"], check=True)
        print(f"Karta {interface_name} została włączona.")
    except subprocess.CalledProcessError as e:
        print(f"Błąd przy włączaniu karty {interface_name}: {e}")

def main():
    interfaces = get_network_interfaces()
    if not interfaces:
        print("Brak kart sieciowych do wyświetlenia.")
        return

    print("Lista kart sieciowych:")
    for i, interface in enumerate(interfaces, start=1):
        print(f"{i}. {interface}")

    while True:
        try:
            choice = int(input("Wybierz numer karty do wyłączenia lub włączenia (0 - wyjście): "))
