                action = input(f"Czy chcesz wyłączyć '{interface_name}' (wpisz 'wyłącz' lub 'włącz')? ")
                if action.lower() == 'wyłącz':
                    disable_network_interface(interface_name)
                elif action.lower() == 'włącz':
                    enable_network_interface(interface_name)
