```python
import xml.etree.ElementTree as ET

def extract_scheme_urls(manifest_file):
    """
    Extracts all scheme URLs from the AndroidManifest.xml file.

    Args:
        manifest_file (str): Path to the AndroidManifest.xml file.

    Returns:
        list: A list of scheme URLs found in the manifest file.
    """
    scheme_urls = []
    tree = ET.parse(manifest_file)
    root = tree.getroot()

    for node in root.iter('activity'):
        for attr in node.attrib:
            if attr.startswith('android:scheme'):
                scheme_urls.append(node.attrib[attr])

    for node in root.iter('service'):
        for attr in node.attrib:
            if attr.startswith('android:scheme'):
                scheme_urls.append(node.attrib[attr])

    for node in root.iter('receiver'):
        for attr in node.attrib:
            if attr.startswith('android:scheme'):
                scheme_urls.append(node.attrib[attr])

    for node in root.iter('provider'):
        for attr in node.attrib:
            if attr.startswith('android:scheme'):
                scheme_urls.append(node.attrib[attr])

    return scheme_urls

# Example usage
manifest_path = 'path/to/your/AndroidManifest.xml'
