// Function to read temperature from DHT sensor
float readTemperature() {
  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();

  if (isnan(humidity) || isnan(temperature)) {
    return -1.0; // Return -1 if reading fails
  }

  return temperature;
}

// Function to send data over radio module
void sendData() {
  float temperature = readTemperature();

  if (temperature != -1.0) {
    // Pack data into a byte array
    byte data[5];
    data[0] = 0x01; // Data type identifier (temperature)
    data[1] = (temperature * 100) >> 8; // Temperature value (16-bit integer)
    data[2] = (temperature * 100) & 0xFF; // Temperature value (low byte)
    data[3] = 0x00; // Status byte (0 for normal data)
    data[4] = 0x00; // Status byte (0 for normal data)

    // Send data over radio module
    radio.beginPacket();
    radio.write(data, 5);
    radio.endPacket();
  }
}

void setup() {
  // Initialize DHT sensor
  dht.begin();

  // Initialize radio module
  radio.setBaudRate(RADIO_MODULE_BAUD_RATE);
  radio.begin();

