            if (node.data == source) {
                node.neighbors.push_back(destination);
                return;
            }
        }
        cout << "Source node not found." << endl;
    }

    // Вывод графа
    void printGraph() {
        for (const auto& node : nodes) {
            cout << "Node: " << node.data << " Neighbors: ";
            for (const auto& neighbor : node.neighbors) {
                cout << neighbor << " ";
            }
            cout << endl;
        }
    }
};

