MergeResult* mergeTwoLists(ListNode* l1, ListNode* l2) {
    MergeResult result = {NULL, NULL};
    ListNode *current = NULL;
    ListNode *l1_temp = l1;
    ListNode *l2_temp = l2;

    // 合并两个链表
    while (l1_temp && l2_temp) {
        if (l1_temp->val < l2_temp->val) {
            if (!result.head) {
                result.head = l1_temp;
                result.tail = l1_temp;
            } else {
                result.tail->next = l1_temp;
                result.tail = l1_temp;
            }
            l1_temp = l1_temp->next;
