            result.head = l1_temp;
        } else {
            result.tail->next = l1_temp;
        }
        result.tail = l1_temp;
    } else if (l2_temp) {
        if (!result.head) {
            result.head = l2_temp;
        } else {
            result.tail->next = l2_temp;
        }
        result.tail = l2_temp;
    }

    return &result;
}

// 打印链表
void printList(ListNode* head) {
    ListNode *current = head;
    while (current) {
        printf("%d -> ", current->val);
        current = current->next;
    }
    printf("NULL\n");
}

