```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_STATIONS 100
#define MAX_DEPTH 10000

// Structure to represent a station
typedef struct {
    int depth;
    int time;
} Station;

// Comparison function for the heap
int compareStations(const void *a, const void *b) {
    Station *s1 = (Station *)a;
    Station *s2 = (Station *)b;
    return s1->time - s2->time;
}

int main() {
    int numStations, initialOxygen, finalDepth, oxygenPerStation;
    scanf("%d %d %d %d", &numStations, &initialOxygen, &finalDepth, &oxygenPerStation);

    Station stations[MAX_STATIONS];
    for (int i = 0; i < numStations; i++) {
        scanf("%d", &stations[i].depth);
        stations[i].time = 0; // Time to refill is not directly provided, so we'll calculate it later
    }

    // Calculate the time to refill oxygen at each station
    for (int i = 0; i < numStations; i++) {
        stations[i].time = (int)ceil((double)oxygenPerStation / (finalDepth - stations[i].depth));
    }

    // Create a max heap to store stations
    qsort(stations, numStations, sizeof(Station), compareStations);

    int currentDepth = 0;
    int totalTime = 0;
    int remainingOxygen = initialOxygen;

    // Use a max heap to prioritize stations with the least time to refill
    while (currentDepth < finalDepth) {
        Station *station = (Station *)heap32_top(stations, numStations);
        if (station->depth > currentDepth) {
            // Refill oxygen at the station
            remainingOxygen += oxygenPerStation;
            totalTime += station->time;
            heap32_pop(stations, numStations);
        } else {
            // Move to the next station
            currentDepth = station->depth;
        }

        // Check if we can reach the final depth
        if (remainingOxygen >= (finalDepth - currentDepth) * (int)ceil((double)oxygenPerStation / (finalDepth - currentDepth))) {
            printf("%d\n", totalTime);
            return 0;
        }
    }

    // If we can't reach the final depth, print the maximum depth reached
    printf("%d %d\n", -1, currentDepth);

    return 0;
}
```

