```c
#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846

// Function to calculate the distance between two points
double distance(double x1, double y1, double x2, double y2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

// Function to determine the number of intersection points
int circleIntersection(double x1, double y1, double r1, double x2, double y2, double r2) {
    double d = distance(x1, y1, x2, y2);

    if (d > r1 + r2) {
        return 0; // No intersection
    } else if (d < abs(r1 - r2)) {
        return 0; // One circle is completely inside the other
    } else {
        return 2; // Two intersection points
    }
}

