#include <iostream>

#define PAYRATE 12.00
#define TAXRATE_300 0.15
#define TAXRATE_450 0.20
#define TAXRATE_REST 0.25
#define OVERTIME 40

using namespace std;

int main() {
    unsigned int hours;
    double grossPay, taxes, netPay;

    cout << "Enter hours worked: ";
    cin >> hours;

    if (hours <= OVERTIME) {
        grossPay = hours * PAYRATE;
    } else {
        grossPay = (OVERTIME * PAYRATE) + ((hours - OVERTIME) * (PAYRATE * 1.5));
    }

    if (grossPay <= 300) {
        taxes = grossPay * TAXRATE_300;
    } else if (grossPay <= 450) {
        taxes = grossPay * TAXRATE_450;
    } else {
        taxes = grossPay * TAXRATE_REST;
