#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define PORT 2346
#define IP_ADDRESS "255.255.255.255"
#define INTERVALLE_ENVOI 1 // En secondes
#define INTERVALLE_VISUALISATION 30 // En secondes

typedef struct {
    char message[BUFFER_SIZE];
    struct sockaddr_in sender;
} Message;

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <message>\n", argv[0]);
        exit(1);
    }

    char *message = argv[1];
    int sockfd;
    struct sockaddr_in servaddr;
    Message msg;
    int tb[100]; // Tableau pour stocker les adresses IP et les numéros de port
    int i = 0;

    // Création du socket UDP
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Erreur de création du socket");
        exit(1);
    }

    // Configuration de l'adresse du serveur
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = inet_addr(IP_ADDRESS);
    servaddr.sin_port = htons(PORT);

    // Processus père
    while (1) {
        // Envoi du message
        msg.sender.sin_family = AF_INET;
        msg.sender.sin_addr.s_addr = inet_addr(IP_ADDRESS);
        msg.sender.sin_port = htons(PORT);
        strcpy(msg.message, message);
        sendto(sockfd, (char *)&msg, sizeof(msg), 0, (struct sockaddr *)&servaddr, sizeof(servaddr));

        // Visualisation du tableau tb toutes les 30 secondes
        if (i % INTERVALLE_VISUALISATION == 0) {
            printf("Tableau tb:\n");
            for (int j = 0; j < i; j++) {
                printf("Adresse IP: %s, Numéro de port: %d\n", inet_ntoa(tb[j].sin_addr), ntohs(tb[j].sin_port));
            }
            printf("\n");
        }
        i++;
        sleep(INTERVALLE_ENVOI);
    }

    // Processus fils
    while (1) {
        char buffer[BUFFER_SIZE];
        socklen_t addrlen = sizeof(servaddr);
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&servaddr, &addrlen);
        if (n > 0) {
            Message *msg = (Message *)malloc(sizeof(Message));
            memcpy(msg, buffer, n);
            if (strcmp(msg->message, message) == 0) {
                tb[i] = servaddr;
                i++;
            }
            free(msg);
        }
        sleep(1);
    }

    close(sockfd);
    return 0;
}
```

