int leggiMagazzino(FILE *file, Magazzino *magazzino) {
    char codice[MAX_CODIGO_PRODOTTO + 1];
    float costo;
    int quantita;
    int i;

    magazzino->numProdotti = 0;

    while (fscanf(file, "%s %f %d", codice, &costo, &quantita) == 3) {
        for (i = 0; i < magazzino->numProdotti; i++) {
            if (strcmp(codice, magazzino->prodotti[i].codice) == 0) {
                magazzino->prodotti[i].costo = costo;
                magazzino->prodotti[i].quantita = quantita;
                return 1;  // Prodotto già presente
            }
        }
        magazzino->prodotti[magazzino->numProdotti].codice[0] = '\0';
        strcpy(magazzino->prodotti[magazzino->numProdotti].codice, codice);
        magazzino->prodotti[magazzino->numProdotti].costo = costo;
        magazzino->prodotti[magazzino->numProdotti].quantita = quantita;
        magazzino->numProdotti++;
    }

    return 0;  // Fine del file
}

int controllaAggiornamento(const char *codice, int variazione, Magazzino *magazzino) {
    for (int i = 0; i < magazzino->numProdotti; i++) {
