        if (strcmp(codice, magazzino->prodotti[i].codice) == 0) {
            magazzino->prodotti[i].quantita += variazione;
            *valoreTotale = valoreTotaleOld + magazzino->prodotti[i].costo * magazzino->prodotti[i].quantita;
            return;
        }
    }
}

void stampaMagazzino(Magazzino *magazzino, FILE *file) {
