```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define INF INT_MAX

typedef struct {
    int vertex;
    int distance;
    int previous;
} Edge;

typedef struct {
    int vertices;
    int edges;
    int adj[100][100]; // 假设最大顶点数为 100
} Graph;

void initializeGraph(Graph *graph, int vertices) {
    graph->vertices = vertices;
    for (int i = 0; i < vertices; i++) {
        for (int j = 0; j < vertices; j++) {
            graph->adj[i][j] = INF;
        }
    }
}

void addEdge(Graph *graph, int u, int v, int weight) {
    graph->adj[u][v] = weight;
    graph->adj[v][u] = weight; // 由于图是无向的，所以需要添加双向边
}

void dijkstra(Graph *graph, int start) {
    int vertices = graph->vertices;
    int visited[vertices];
    Edge edges[vertices];
    int edgeCount = 0;

    for (int i = 0; i < vertices; i++) {
        visited[i] = 0;
        edges[i].vertex = i;
        edges[i].distance = INF;
        edges[i].previous = -1;
    }

    edges[start].distance = 0;

    while (1) {
        int minDistance = INF;
        int minVertex = -1;

        for (int i = 0; i < vertices; i++) {
            if (!visited[i] && edges[i].distance < minDistance) {
                minDistance = edges[i].distance;
                minVertex = i;
            }
        }

        if (minVertex == -1) break; // 所有顶点都被访问

        visited[minVertex] = 1;

        for (int i = 0; i < vertices; i++) {
            int distance = edges[minVertex].distance + graph->adj[minVertex][i];
            if (distance < edges[i].distance) {
                edges[i].distance = distance;
                edges[i].previous = minVertex;
            }
        }
    }

    // 打印结果
    printf("Shortest paths from vertex %d:\n", start);
    for (int i = 0; i < vertices; i++) {
        if (edges[i].distance != INF) {
            printf("Vertex %d: Distance = %d\n", i, edges[i].distance);
            printPath(edges, i, start);
        }
    }
}

void printPath(Edge *edges, int start, int end) {
    int vertex = end;
    printf(" -> ");
