// 定义二叉树节点结构体
typedef struct Node {
    int val;
    struct Node *left;
    struct Node *right;
} Node;

// 函数声明
Node* createNode(int val, Node* left, Node* right);
void inorder(Node* root, char* traversal);
void preorder(Node* root, char* traversal);
void postorder(Node* root, char* traversal);

int main() {
    int n;
    scanf("%d", &n);

    Node* root = NULL;
    for (int i = 0; i < n; i++) {
        int val, left, right;
        scanf("%d %d %d", &val, &left, &right);
        root = createNode(val, (left == -1) ? NULL : &root, (right == -1) ? NULL : &root);
    }

    char preorder[100], inorder[100], postorder[100];
    preorder[0] = '\0';
    inorder[0] = '\0';
