    node->left = left;
    node->right = right;
    return node;
}

// 中序遍历函数
void inorder(Node* root, char* traversal) {
    if (root == NULL) return;
    inorder(root->left, traversal);
    strcat(traversal, &root->val);
    inorder(root->right, traversal);
}

