    strcat(traversal, &root->val);
    preorder(root->left, traversal);
    preorder(root->right, traversal);
}

// 后序遍历函数
void postorder(Node* root, char* traversal) {
    if (root == NULL) return;
    postorder(root->left, traversal);
    postorder(root->right, traversal);
    strcat(traversal, &root->val);
