void server_code() {
    // Create socket
    server_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (server_socket < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        // Receive datagram from client
        client_socket = recvfrom(server_socket, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &addr_len);
        if (client_socket < 0) {
            perror("Receive failed");
            continue;
        }

        // Extract name from buffer
        strncpy(name, buffer, client_socket);
        name[client_socket] = '\0';

        // Convert name to uppercase
        for (int i = 0; i < client_socket; i++) {
            if (islower(name[i])) {
                name[i] = toupper(name[i]);
            }
        }

        // Send response to client
        sendto(client_socket, name, strlen(name), 0, (struct sockaddr *)&client_addr, addr_len);
    }
}
