    Node* left;
    Node* right;

    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Функция для создания бинарного дерева из вектора
Node* fullTree(const std::vector<int>& elements) {
    Node* root = nullptr;
    for (const auto& element : elements) {
        root = AddNode(root, element);
    }
