```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// 比较函数，用于排序
int compare(const void *a, const void *b) {
    return *(const char *)a - *(const char *)b;
}

int main() {
    char str1[100], str2[100];
    int len1, len2;

    // 从键盘输入第一个字符串
    printf("Enter the first string: ");
    fgets(str1, sizeof(str1), stdin);
    str1[strcspn(str1, "\n")] = 0; // 去除换行符
    len1 = strlen(str1);

    // 从键盘输入第二个字符串
    printf("Enter the second string: ");
    fgets(str2, sizeof(str2), stdin);
    str2[strcspn(str2, "\n")] = 0; // 去除换行符
    len2 = strlen(str2);

    // 合并两个字符串
    char merged[len1 + len2 + 1];
    strcpy(merged, str1);
    strcat(merged, str2);

    // 排序合并后的字符串
    qsort(merged, len1 + len2, sizeof(char), compare);

    // 删除重复字符
    char *unique = merged;
    for (char *ptr = merged + 1; ptr <= merged + len1 + len2; ptr++) {
        if (*ptr != *unique) {
            *unique++ = *ptr;
        }
    }
    *unique = 0;

    // 输出结果
    printf("Sorted and merged string: %s\n", merged);

    return 0;
}
```

