#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_CLIENTS 10

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t sin_size;
    fd_set read_fds;
    int max_fd;

    // Создание сервера
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(1);
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(1);
    }

    // Инициализация набора фд
    FD_ZERO(&read_fds);
    FD_SET(server_fd, &read_fds);
    max_fd = server_fd;

    while (1) {
        // Ожидание ввода/вывода
        read_fds.fd_count = 0;
        FD_SET(server_fd, &read_fds);
        for (int i = 0; i <= max_fd; i++) {
            if (FD_ISSET(i, &read_fds)) {
                read_fds.fd_count++;
                if (i > max_fd) {
                    max_fd = i;
                }
            }
        }

        // Обработка клиентов
        for (int i = 0; i <= max_fd; i++) {
            if (FD_ISSET(i, &read_fds)) {
                if (i == server_fd) {
                    // Прибытие нового клиента
                    sin_size = sizeof(client_addr);
                    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &sin_size);
                    if (client_fd < 0) {
                        perror("Accept failed");
                        continue;
                    }

                    FD_SET(client_fd, &read_fds);
                    if (client_fd > max_fd) {
                        max_fd = client_fd;
                    }

                    printf("New client connected: %s\n", inet_ntoa(client_addr.sin_addr));
                } else {
                    // Обработка клиента
                    char buffer[1024];
                    int bytes_read = read(i, buffer, sizeof(buffer));
                    if (bytes_read > 0) {
                        buffer[bytes_read] = '\0';
                        printf("Client %s: %s\n", inet_ntoa(client_addr.sin_addr), buffer);

                        // Отправка ответа клиенту
                        char response[] = "Server received message";
                        write(i, response, strlen(response));
                    } else if (bytes_read == 0) {
                        // Клиент отключился
                        printf("Client %s disconnected\n", inet_ntoa(client_addr.sin_addr));
                        FD_CLR(i, &read_fds);
                        close(i);
                    } else {
                        perror("Read failed");
                    }
                }
            }
        }

        // Ожидание новых клиентов
        if (FD_ISSET(server_fd, &read_fds)) {
            // Прибытие нового клиента
            sin_size = sizeof(client_addr);
            client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &sin_size);
            if (client_fd < 0) {
                perror("Accept failed");
                continue;
            }

            FD_SET(client_fd, &read_fds);
            if (client_fd > max_fd) {
                max_fd = client_fd;
            }

            printf("New client connected: %s\n", inet_ntoa(client_addr.sin_addr));
        }
    }

    close(server_fd);
    return 0;
}
```

Этот код создает однопоточный сервер, который слушает порт 8080 и обрабатывает клиентов с использованием системного вызова `select`. Сервер может обрабатывать несколько клиентов одновременно, используя псевдопараллельную модель, в которой каждый клиент считается как отдельный поток.

Клиенты отправляют сообщения серверу, а сервер отправляет ответы клиентам. Сервер также может обрабатывать отключение клиентов и отправлять уведомления о desconnection.

