**Calculatrice.java**
```java
import java.io.*;
import java.net.*;

public class Calculatrice {
    private ServerSocket serverSocket;
    private Socket clientSocket;
    private DataInputStream inputStream;
    private DataOutputStream outputStream;

    public Calculatrice(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        System.out.println("Calculatrice en attente sur le port " + port);
    }

    public void start() {
        try {
            clientSocket = serverSocket.accept();
            System.out.println("Client connecté");

            inputStream = new DataInputStream(clientSocket.getInputStream());
            outputStream = new DataOutputStream(clientSocket.getOutputStream());

            while (true) {
                String input = inputStream.readUTF();
                if (input.equals("quit")) {
                    break;
                }
                String result = performCalculation(input);
                outputStream.writeUTF(result);
            }

            inputStream.close();
            outputStream.close();
            clientSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private String performCalculation(String input) {
        String[] parts = input.split(" ");
        double num1 = Double.parseDouble(parts[0]);
        double num2 = Double.parseDouble(parts[2]);
        String operator = parts[1];

        switch (operator) {
            case "+":
                return String.valueOf(num1 + num2);
            case "-":
                return String.valueOf(num1 - num2);
            case "*":
                return String.valueOf(num1 * num2);
            case "/":
                if (num2 != 0) {
                    return String.valueOf(num1 / num2);
                } else {
                    return "Erreur : division par zéro";
                }
            default:
                return "Erreur : opérateur non reconnu";
        }
    }
}
```

