下面是一个使用Java实现上述功能的示例代码：

```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Security Researcher {

    /**
     * 计算wmPoiId + noticeId 和字符串组合的MD5值
     * 
     * @param wmPoiId long类型的wmPoiId
     * @param noticeId long类型的noticeId
     * @param str 字符串
     * @return 计算得到的MD5值
     */
    public static String calculateMD5(long wmPoiId, long noticeId, String str) {
        try {
            // 创建MD5消息摘要器
            MessageDigest md = MessageDigest.getInstance("MD5");

            // 将wmPoiId + noticeId 转换为字符串
            String combined = String.valueOf(wmPoiId) + String.valueOf(noticeId);

            // 将字符串和combined组合起来
            String input = combined + str;

            // 更新消息摘要器
            md.update(input.getBytes());

            // 获取MD5值
            byte[] bytes = md.digest();

            // 将字节数组转换为十六进制字符串
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }
