            sslContext.init(null, trustManagerFactory.getTrustManagers(), null);

            // Create a server socket factory
            ServerSocketFactory serverSocketFactory = sslContext.getServerSocketFactory();

            // Create a server socket
            ServerSocket serverSocket = serverSocketFactory.createServerSocket(443);
            logger.info("HTTPS server started on port 443");

            while (true) {
                Socket socket = serverSocket.accept();
                logger.info("New connection accepted");

                // Create a SSLSocket
                SSLSocket sslSocket = (SSLSocket) socket;
                try {
