    private static final String RECORD_FILE = "mouse_recordings.dat";
    private static final Map<String, HashMap<String, Integer>> recordings = new HashMap<>();
    private static boolean recording = false;

    public static void main(String[] args) {
        // Detect screen size
        Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        System.out.println("Screen size: " + screenSize);

        // Create GUI
        JFrame frame = new JFrame("Mouse Recorder");
        JTable table = new JTable();
        table.setModel(new DefaultTableModel());
        JScrollPane scrollPane = new JScrollPane(table);
        frame.add(scrollPane);
        frame.setVisible(true);

        // Add mouse listener
        frame.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (recording) {
                    // Record mouse movement
                    recordMouseMovement(e.getX(), e.getY());
                }
            }
        });

        // Keyboard shortcuts
        frame.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_SHIFT && e.isModifierDown(KeyEvent.VK_P)) {
                    startRecording();
                } else if (e.getKeyCode() == KeyEvent.VK_SHIFT && e.isModifierDown(KeyEvent.VK_L)) {
                    stopRecording();
                }
            }
        });
    }

    private static void startRecording() {
        recording = true;
        System.out.println("Recording started");
    }

    private static void stopRecording() {
        recording = false;
        System.out.println("Recording stopped");
        saveRecordings();
    }

    private static void recordMouseMovement(int x, int y) {
        if (recording) {
            String key = x + "," + y;
            HashMap<String, Integer> recordingMap = recordings.computeIfAbsent(System.currentTimeMillis() + "", k -> new HashMap<>());
            recordingMap.put(key, recordingMap.size());
        }
    }

    private static void saveRecordings() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(RECORD_FILE))) {
            oos.writeObject(recordings);
            System.out.println("Recordings saved to " + RECORD_FILE);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void loadRecordings() {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(RECORD_FILE))) {
            recordings.putAll((Map<String, HashMap<String, Integer>>) ois.readObject());
            System.out.println("Recordings loaded");
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

