    @Bean
    public WebSocketMessageBrokerConfigurer messageBrokerConfigurer() {
        return new WebSocketMessageBrokerConfigurer() {
            @Override
            public void configureMessage Brokers(MessageBrokerRegistry registry) {
                registry.enableSimpleBroker("/topic"); // Enable simple message broker for /topic
                registry.setApplicationDestinationPrefixes("/app"); // Set application destination prefix
            }
        };
    }

