    }

    public String getKey() {
        return key;
    }

    public Object getValue() {
        return value;
    }

    @Override
    public String toString() {
        return "MiniDBEntry{" +
                "key='" + key + '\'' +
                ", value=" + value +
                '}';
    }
}
```

### Step 2: Define the `MiniDB` Class

The `MiniDB` class will use a `HashMap` to store the entries and provide methods for adding, retrieving, and removing entries.

```java
import java.io.*;
import java.util.HashMap;
import java.util.Map;

public class MiniDB implements Serializable {
    private static final long serialVersionUID = 1L;
    private Map<String, MiniDBEntry> entries;

    public MiniDB() {
        this.entries = new HashMap<>();
    }

    public void addEntry(String key, Object value) {
        entries.put(key, new MiniDBEntry(key, value));
    }

    public Object getEntry(String key) {
        return entries.get(key);
    }

    public void removeEntry(String key) {
        entries.remove(key);
    }

    public int size() {
        return entries.size();
    }

    @Override
    public String toString() {
        return "MiniDB{" +
                "entries=" + entries +
                '}';
    }
}
```

### Step 3: Define the `MiniDBSerializer` Class

The `MiniDBSerializer` class will handle serialization and deserialization of the `MiniDB` object.

```java
import java.io.*;

public class MiniDBSerializer {
    public void serialize(MiniDB db, String filename) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filename))) {
            oos.writeObject(db);
        }
    }

    public MiniDB deserialize(String filename) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
            return (MiniDB) ois.readObject();
        }
    }
}
```

### Step 4: Main Method

Here's a simple main method to demonstrate how to use the `MiniDB` and `MiniDBSerializer` classes.

```java
