    public static void main(String[] args) {
        MiniDB db = new MiniDB();

        db.addEntry("name", "Cohere");
        db.addEntry("age", 1);

        System.out.println("Entries: " + db);

        try {
            MiniDBSerializer serializer = new MiniDBSerializer();
            serializer.serialize(db, "database.ser");
            System.out.println("Serialized and saved to database.ser");
        } catch (IOException e) {
            e.printStackTrace();
        }

        MiniDB loadedDB = null;
