        sslContext.init(null, null, new SecureRandom());
        SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();

        try {
            // Create a socket and establish SSL connection
            SSLSocket sslSocket = (SSLSocket) sslSocketFactory.createSocket(SERVER_HOST, SERVER_PORT);
            sslSocket.startHandshake();

            // Get the server certificate
            SSLSession session = sslSocket.getSession();
            X509TrustManager trustManager = new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                    // Trust the server certificate (you might want to add more validation)
                    if (isValidServerCertificate(sslSocket.getSession().getPeerCertificates())) {
                        sslSocket.setSoTimeout(0); // Disable timeout
