### 4. scripts.js
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const categorySelector = document.querySelector('.category-selector');
    const modelContainer = document.querySelector('.model-container');
    const pagination = document.querySelector('.pagination');

    // 模拟数据
    const categories = {
        '项目文件': ['model1.glb', 'model2.glb', ...],
        '文档': ['doc1.glb', 'doc2.glb', ...],
        // 添加更多分类
    };

    let currentCategory = '项目文件';
    let currentPage = 1;

    // 更新分类
    function updateCategory(category) {
        currentCategory = category;
        updateModels();
    }

    // 更新模型
    function updateModels() {
        modelContainer.innerHTML = '';
        const models = categories[currentCategory];
        const modelsPerPage = 20;
        const modelsPerPageRow = 4;
        const modelsPerPageColumn = 5;
        const totalPages = Math.ceil(models.length / modelsPerPage);

        for (let i = (currentPage - 1) * modelsPerPage; i < currentPage * modelsPerPage; i++) {
            const model = models[i];
            const img = document.createElement('img');
            img.src = `models/${currentCategory}/${model}`;
            img.alt = model;
            img.addEventListener('click', () => downloadModel(model));
            modelContainer.appendChild(img);

            if (i % modelsPerPageRow === modelsPerPageRow - 1) {
                modelContainer.appendChild(document.createElement('br'));
            }
        }

        pagination.innerHTML = '';
        for (let i = 1; i <= totalPages; i++) {
            const button = document.createElement('button');
            button.textContent = i;
            button.addEventListener('click', () => changePage(i));
            pagination.appendChild(button);
        }
    }

    // 切换分类
    categorySelector.addEventListener('change', (e) => {
        updateCategory(e.target.value);
    });

    // 切换页码
    function changePage(page) {
        currentPage = page;
        updateModels();
    }

    // 下载模型
    function downloadModel(model) {
        const link = document.createElement('a');
        link.href = `models/${currentCategory}/${model}`;
        link.download = model;
        link.click();
    }

    // 初始化
    updateModels();
});
```

### 5. 模型文件夹结构
```
models/
├── project1/
│   ├── model1.glb
│   ├── model2.glb
│   └── ...
├── doc1/
│   ├── doc1.glb
│   └── ...
└── ...
```

### 说明
- **分类选择**：用户可以通过单选框选择不同的模型分类。
- **模型预览**：每个模型都有一个预览图，点击预览图可以直接下载模型文件。
- **翻页**：当模型数量超过每页20个时，会显示翻页按钮，用户可以切换页码。
- **自动加载**：模型文件放在指定的文件夹中，刷新页面后自动加载所有模型。

这个实现方案是一个基本的示例，您可以根据实际需求进行调整和优化。

