```

### Step 2: JavaScript to Handle Form Submission

Add a JavaScript function to handle the form submission and save the data to a `.txt` file.

```javascript
let leaderboardData = [];

function submitLeaderboardEntry(event) {
    event.preventDefault();

    const name = document.getElementById('name').value;
    const score = document.getElementById('score').value;

    // Example: Save to local storage or a server (for demonstration, we'll use local storage)
    leaderboardData.push({ name, score });
    localStorage.setItem('leaderboardData', JSON.stringify(leaderboardData));

    // Clear the form
    document.getElementById('name').value = '';
    document.getElementById('score').value = '';

    // Optionally, display a success message
    alert('Entry submitted successfully!');

    // Save to a text file (server-side)
    saveToTextFile(leaderboardData);
}

function saveToTextFile(data) {
    // Convert data to a string
    const dataString = JSON.stringify(data, null, 2);

    // Create a blob
    const blob = new Blob([dataString], { type: 'text/plain' });

    // Create a URL for the blob
    const url = URL.createObjectURL(blob);

    // Create a link and trigger a download
    const a = document.createElement('a');
    a.href = url;
    a.download = 'leaderboard.txt';
    a.click();

    // Clean up
    URL.revokeObjectURL(url);
}
