**JavaScript (script.js):**

```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const canvasWidth = canvas.width;
const canvasHeight = canvas.height;

const cellSize = 20;
const gridSize = canvasWidth / cellSize;

let snake = [{ x: 100, y: 100 }, { x: 90, y: 100 }, { x: 80, y: 100 }];
let direction = 'right';
let speed = 5;
let score = 0;
let gameInterval;

function drawGrid() {
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);
    for (let x = 0; x <= gridSize; x++) {
        for (let y = 0; y <= gridSize; y++) {
            ctx.strokeStyle = '#ccc';
            ctx.lineWidth = 1;
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
    }
}

function drawSnake() {
    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x, segment.y);
    });
}

function drawFood() {
    const foodX = Math.floor(Math.random() * gridSize) * cellSize;
    const foodY = Math.floor(Math.random() * gridSize) * cellSize;
    ctx.fillStyle = 'red';
    ctx.fillRect(foodX, foodY);
}

function moveSnake() {
    const head = { ...snake[0] };
    switch (direction) {
        case 'right':
            head.x += cellSize;
            break;
        case 'left':
            head.x -= cellSize;
            break;
        case 'down':
            head.y += cellSize;
            break;
        case 'up':
            head.y -= cellSize;
            break;
    }

    snake.unshift(head);

    if (collidesWithWall() || collidesWithSelf()) {
        clearInterval(gameInterval);
        alert('Game Over! Press OK to restart.');
        snake = [{ x: 100, y: 100 }, { x: 90, y: 100 }, { x: 80, y: 100 }];
        direction = 'right';
        score = 0;
    } else if (collidesWithFood()) {
        score += 10;
        snake.push({ x: snake[snake.length - 1].x, y: snake[snake.length - 1].y });
        if (score % 100 === 0) {
            speed++;
        }
    }
}

function collidesWithWall() {
    return snake[0].x < 0 || snake[0].x >= canvasWidth || snake[0].y < 0 || snake[0].y >= canvasHeight;
}

function collidesWithSelf() {
    for (let i = 1; i < snake.length; i++) {
        if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
            return true;
        }
    }
    return false;
}

function collidesWithFood() {
    return snake[0].x === Math.floor(Math.random() * gridSize) * cellSize &&
           snake[0].y === Math.floor(Math.random() * gridSize) * cellSize;
}

function update() {
    moveSnake();
    drawGrid();
    drawSnake();
    drawFood();
    requestAnimationFrame(update);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' && direction !== 'left') {
        direction = 'right';
    } else if (e.key === 'ArrowLeft' && direction !== 'right') {
        direction = 'left';
    } else if (e.key === 'ArrowDown' && direction !== 'up') {
        direction = 'down';
    } else if (e.key === 'ArrowUp' && direction !== 'down') {
        direction = 'up';
    }
});

drawGrid();
drawFood();
update();
```

In this code:
- We have a simple HTML structure with a canvas element where the game will be displayed.
- CSS is used to style the canvas and the game elements.
- JavaScript handles the game logic, including moving the snake, checking for collisions, and updating the game state.
- The `drawGrid`, `drawSnake`, and `drawFood` functions are used to render the game elements on the canvas.
- The `moveSnake` function updates the snake's position based on the current direction.
- Collision detection is implemented to check for walls, the snake's own body, and food.
- The game loop uses `requestAnimationFrame` to continuously update and render the game.
- Keyboard input is handled to change the snake's direction.

This is a basic Snake game, and you can further enhance it by adding features like a score counter, different levels, power-ups, and more complex graphics. Remember, as a security researcher, it's essential to ensure that any game or application you create is secure and free from vulnerabilities.

