**script.js:**

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const quizForm = document.getElementById('quizForm');
    const quizResults = document.getElementById('quizResults');

    quizForm.addEventListener('submit', function(event) {
        event.preventDefault();
        generateQuiz();
    });

    function generateQuiz() {
        const board = document.getElementById('board').value;
        const questionType = document.getElementById('questionType').value;
        const difficulty = document.getElementById('difficulty').value;
        const numQuestions = document.getElementById('numQuestions').value;
        const customText = document.getElementById('customText').value;

        fetch('/generate-quiz', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ board, questionType, difficulty, numQuestions, customText })
        })
        .then(response => response.json())
        .then(data => {
            quizResults.innerHTML = `<h2>Generated Quiz</h2><pre>${data.questions}</pre>`;
        })
        .catch(error => console.error('Error:', error));
    }
});
```

## Backend (Node.js with Express and OpenAI API)

**server.js:**

```javascript
const express = require('express');
const axios = require('axios');
const dotenv = require('dotenv').config();

const app = express();
const port = 3000;

app.use(express.json());

// ... (OpenAI API key setup) ...

app.post('/generate-quiz', (req, res) => {
    const { board, questionType, difficulty, numQuestions, customText } = req.body;

    // Example OpenAI API call (replace with your actual API key and endpoint)
    const apiKey = process.env.OPENAI_API_KEY;
    const endpoint = 'https://api.openai.com/v1/completions';

    const prompt = `Generate ${numQuestions} ${questionType} questions on ${board} radiology. Difficulty: ${difficulty}. Include ${customText}`;

    axios.post(endpoint, {
        model: 'text-davinci-003', // Replace with your chosen model
        prompt,
        max_tokens: 500,
        temperature: 0.7
    }, {
        headers: {
            'Authorization': `Bearer ${apiKey}`,
            'Content-Type': 'application/json'
        }
    })
    .then(response => {
        const questions = response.data.choices[0].text.trim().split('\n');
        res.json({ questions });
    })
    .catch(error => {
        console.error('OpenAI API Error:', error);
        res.status(500).json({ error: 'Failed to generate quiz' });
    });
});

app.listen(port, () => {
    console.log(`Server listening on port ${port}`);
});
```

**OpenAI API Key:**

* Replace the placeholder `OPENAI_API_KEY` in `server.js` with your actual OpenAI API key.

## Step-by-Step Instructions:

1. **Frontend Setup:**
    * Create the HTML, CSS, and JavaScript files as shown above.
    * Ensure you have a local development server (e.g., Live Server extension for VS Code) to host the frontend.

2. **Backend Setup:**
    * Install Node.js and npm (Node Package Manager).
    * Create a new project directory and initialize npm: `mkdir radiology-quiz && cd radiology-quiz && npm init -y`.
    * Install required dependencies: `npm install express axios dotenv`.
    * Create the `server.js` file with the provided code.
    * Set up your OpenAI API key in the `server.js` file or use an environment variable.

3. **Run the Application:**
    * Start the Node.js server: `node server.js`.
    * Access the frontend in your browser at `http://localhost:3000`.

4. **OpenAI API Integration:**
    * Obtain an OpenAI API key from the OpenAI website.
    * Replace the placeholder API key in the `server.js` file with your actual key.

5. **Testing:**
    * Fill out the frontend form with different board, question type, difficulty, and custom text.
    * Click "Generate Quiz" and verify that the backend successfully calls OpenAI and returns the generated questions to the frontend.

Remember to handle API rate limits and errors appropriately in a production environment.

