```javascript
document.addEventListener('DOMContentLoaded', function() {
  // افترض أن لديك بيانات المنتجات في مصفوفة
  const products = [
    { id: 1, name: 'المنتج الأول', price: 100, description: 'وصف المنتج الأول' },
